	 * Returns the binary DER in encoded string form.  The ARG1 indicates the encoding and can be base64, hex, uu, quoted-printable, base32, or modbase64.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#GetEncodedDer
	 * @param ?string $encoding
	 * @return ?string
	 */
	function encodedDer($encoding) {
		return CkAsn_encodedDer($this->_cPtr,$encoding);
	}

	/**
	 * Returns the last ASN.1 sub-item.  This method can be called immediately after any Append* method to access the appended item.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#GetLastSubItem
	 * @return ?CkAsn
	 */
	function GetLastSubItem() {
		return chilkat::_obj(CkAsn_GetLastSubItem($this->_cPtr),'CkAsn');
	}

	/**
	 * Returns the Nth ASN.1 sub-item.  The 1st sub-item is at index 0.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#GetSubItem
	 * @param int $index
	 * @return ?CkAsn
	 */
	function GetSubItem($index) {
		return chilkat::_obj(CkAsn_GetSubItem($this->_cPtr,$index),'CkAsn');
	}

	/**
	 * Loads ASN.1 from the XML representation (such as that created by the AsnToXml method).
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#LoadAsnXml
	 * @param ?string $xmlStr
	 * @return bool
	 */
	function LoadAsnXml($xmlStr) {
		return CkAsn_LoadAsnXml($this->_cPtr,$xmlStr);
	}

	/**
	 * Loads ASN.1 from the binary DER contained in ARG1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#LoadBd
	 * @param CkBinData $bd
	 * @return bool
	 */
	function LoadBd($bd) {
		return CkAsn_LoadBd($this->_cPtr,$bd);
	}

	/**
	 * Loads ASN.1 from binary DER.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#LoadBinary
	 * @param CkByteData $derBytes
	 * @return bool
	 */
	function LoadBinary($derBytes) {
		return CkAsn_LoadBinary($this->_cPtr,$derBytes);
	}

	/**
	 * Loads ASN.1 from a binary DER file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#LoadBinaryFile
	 * @param ?string $path
	 * @return bool
	 */
	function LoadBinaryFile($path) {
		return CkAsn_LoadBinaryFile($this->_cPtr,$path);
	}

	/**
	 * Loads ASN.1 from an encoded string.  The ARG2 can be base64, hex, uu, quoted-printable, base32, or modbase64.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#LoadEncoded
	 * @param ?string $asnContent
	 * @param ?string $encoding
	 * @return bool
	 */
	function LoadEncoded($asnContent,$encoding) {
		return CkAsn_LoadEncoded($this->_cPtr,$asnContent,$encoding);
	}

	/**
	 * Sets the content of this primitive ASN.1 item.  The ARG2 may be any of the following encodings: Base64, Hex, Base58, modBase64, Base32, UU, QP (for quoted-printable), URL (for url-encoding),  Q, B, url_oath, url_rfc1738, url_rfc2396, and url_rfc3986.   The ARG2 name is case insensitive (for example, both Base64 and base64 are treated the same).
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#SetEncodedContent
	 * @param ?string $encodedBytes
	 * @param ?string $encoding
	 * @return bool
	 */
	function SetEncodedContent($encodedBytes,$encoding) {
		return CkAsn_SetEncodedContent($this->_cPtr,$encodedBytes,$encoding);
	}

	/**
	 * Appends the ASN.1 in binary DER format to ARG1.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#WriteBd
	 * @param CkBinData $bd
	 * @return bool
	 */
	function WriteBd($bd) {
		return CkAsn_WriteBd($this->_cPtr,$bd);
	}

	/**
	 * Writes the ASN.1 in binary DER form to a file.
	 * @see https://www.chilkatsoft.com/refdoc/phpCkAsnRef.html#WriteBinaryDer
	 * @param ?string $path
	 * @return bool
	 */
	function WriteBinaryDer($path) {
		return CkAsn_WriteBinaryDer($this->_cPtr,$path);
	}
}
